import{_ as a,o as e,a as r,b as i}from"./app.C41L12d5.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/advanced_extreme_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/advanced_extreme_optimization.md","outlineHeaders":[{"level":2,"title":"优化路径：","slug":"优化路径：","link":"#优化路径："},{"level":2,"title":"从中级到高级","slug":"从中级到高级","link":"#从中级到高级"},{"level":2,"title":"详细内容","slug":"详细内容","link":"#详细内容"}],"lastUpdated":1786954352000}'),d={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/advanced_extreme_optimization.md"};function o(s,t,_,c,p,m){return e(),r("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>高级极限打磨</h1><p>本节基于C++ Tensor编程范式，在上文中级性能优化的基础上，进一步介绍Matmul基础API算子的高级极限打磨方法，通过5个高级优化步骤（大包搬运、LoadData3D替代LoadData2D、常量Tiling、UnitFlag优化、L2Cache优化），深入挖掘硬件性能极限。</p><h2 id="优化路径：">优化路径：<a class="header-anchor" href="#优化路径：">​</a></h2><table><thead><tr><th>编号</th><th>优化手段</th><th>等级</th><th>定位</th></tr></thead><tbody><tr><td>1</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#1-l1l0-%E5%8F%8C%E7%BC%93%E5%86%B2-ping-pong-%E5%B8%83%E5%B1%80">L1/L0双缓冲Ping-Pong布局</a></td><td>中级</td><td>流水线骨架</td></tr><tr><td>2</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#2-%E7%BB%86%E7%B2%92%E5%BA%A6%E6%B5%81%E6%B0%B4%E5%90%8C%E6%AD%A5">细粒度流水同步</a></td><td>中级</td><td>流水线骨架</td></tr><tr><td>3</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#3-%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%E5%88%87%E5%88%86">多核并行切分</a></td><td>中级</td><td>并行策略</td></tr><tr><td>4</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#4-datacopyin-%E4%BC%98%E5%85%88%E6%90%AC%E8%BF%90-b-%E7%9F%A9%E9%98%B5">DataCopyIn优先搬运B矩阵</a></td><td>中级</td><td>调度策略</td></tr><tr><td><strong>5</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#5-%E5%A4%A7%E5%8C%85%E6%90%AC%E8%BF%90">大包搬运</a></strong></td><td><strong>高级</strong></td><td><strong>流水线骨架</strong></td></tr><tr><td><strong>6</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#6-loaddata3d-%E6%9B%BF%E4%BB%A3-loaddata2d%E5%87%8F%E5%B0%91%E6%8C%87%E4%BB%A4%E9%98%9F%E5%88%97%E5%8D%A0%E7%94%A8">LoadData3D替代LoadData2D</a></strong></td><td><strong>高级</strong></td><td><strong>指令队列优化</strong></td></tr><tr><td><strong>7</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#7-%E5%B8%B8%E9%87%8F-tiling">常量Tiling</a></strong></td><td><strong>高级</strong></td><td><strong>编译期优化</strong></td></tr><tr><td><strong>8</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#8-unitflag-%E4%BC%98%E5%8C%96">UnitFlag优化</a></strong></td><td><strong>高级</strong></td><td><strong>MMAD-FIXPIPE流水重叠</strong></td></tr><tr><td><strong>9</strong></td><td><strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#9-l2cache-%E4%BC%98%E5%8C%96">L2Cache优化</a></strong></td><td><strong>高级</strong></td><td><strong>MTE2带宽压榨</strong></td></tr></tbody></table><h2 id="从中级到高级">从中级到高级<a class="header-anchor" href="#从中级到高级">​</a></h2><p><a href="./intermediate_optimization.html">中级性能优化</a>通过L1/L0双缓冲、细粒度流水同步、多核并行切分、DataCopyIn优先搬运B矩阵四个步骤，构建了基本的流水线骨架和并行计算框架，实现了MTE2、MTE1、Cube、Fixpipe四个硬件单元的流水并行。</p><p>在此基础上，下列<strong>性能瓶颈</strong>仍有进一步优化空间——这也是高级极限打磨的切入点：</p><table><thead><tr><th>瓶颈</th><th>中级优化后的遗留问题</th><th>对应的高级优化</th></tr></thead><tbody><tr><td><strong>MTE2搬运粒度小</strong></td><td>虽已建立三级流水，但每次DataCopyIn仅搬入一个 <code>baseM×baseK</code> 块，MTE2指令发射次数多</td><td>大包搬运 → 一次搬入 <code>stepKa</code> 个block，减少发射次数</td></tr><tr><td><strong>MTE1指令队列压力大</strong></td><td>LoadData2D需按 <code>CUBE_BLOCK</code>（16B）粒度循环发射多条指令，MTE1队列深度仅32，容易成为瓶颈</td><td>LoadData3D → 单条指令完成整个base切片搬运</td></tr><tr><td><strong>Scalar运行时开销</strong></td><td>Tiling参数在kernel内用Scalar动态计算，增加流水线停顿</td><td>常量Tiling → 模板参数编译期确定，消除Scalar开销</td></tr><tr><td><strong>Cube/Fixpipe串行</strong></td><td>Mmad与Fixpipe指令级同步，Cube需等待结果全部写回才能开始下一轮计算</td><td>UnitFlag → 512B粒度MMAD-FIXPIPE流水重叠</td></tr><tr><td><strong>MTE2带宽瓶颈</strong></td><td>中级优化多核并行后，B矩阵被多核反复从GM读取，MTE2成为性能瓶颈</td><td>L2Cache优化 → B矩阵跨轮驻留L2Cache，减少GM访问</td></tr></tbody></table><h2 id="详细内容">详细内容<a class="header-anchor" href="#详细内容">​</a></h2><p>详细内容请参考 <a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance">Matmul 基础API最佳实践样例</a>，其中高级极限打磨涵盖5个核心步骤：</p><ul><li>5、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#5-%E5%A4%A7%E5%8C%85%E6%90%AC%E8%BF%90">大包搬运</a></strong>：通过 <code>stepKa</code>/<code>stepKb</code> 参数将多个基本块打包为一次DataCopyIn，减少MTE2指令发射次数</li><li>6、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#6-loaddata3d-%E6%9B%BF%E4%BB%A3-loaddata2d%E5%87%8F%E5%B0%91%E6%8C%87%E4%BB%A4%E9%98%9F%E5%88%97%E5%8D%A0%E7%94%A8">LoadData3D替代 LoadData2D</a></strong>：使用 <code>LoadData3DParamsV2</code> 单条指令替代LoadData2D的多条循环发射，降低MTE1指令队列占用</li><li>7、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#7-%E5%B8%B8%E9%87%8F-tiling">常量Tiling</a></strong>：所有Tiling参数通过模板参数在编译期确定，消除运行时Scalar动态计算开销</li><li>8、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#8-unitflag-%E4%BC%98%E5%8C%96">UnitFlag优化</a></strong>：开启UnitFlag实现MMAD-FIXPIPE 512B 粒度流水并行，Cube计算与结果写回重叠执行</li><li>9、<strong><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#9-l2cache-%E4%BC%98%E5%8C%96">L2Cache优化</a></strong>：通过M轴分轮调度使B矩阵跨轮驻留 L2Cache，缓解MTE2带宽压力</li></ul><p>每步优化均包含原理说明与数据流向说明，并附有功能调试（printf、DumpTensor）与性能调试（msOpProf）方法说明。</p><blockquote><p><strong>说明</strong>：中级优化内容请参考 <a href="./intermediate_optimization.html">中级性能优化</a>，上述优化步骤5-9属于高级极限打磨范畴，建议在中级优化完成后逐步叠加。性能数据与理论分析详见README的 <a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#%E6%80%A7%E8%83%BD%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90">性能数据分析</a> 及 <a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_basic_api_high_performance/README.md#%E7%90%86%E8%AE%BA%E6%80%A7%E8%83%BD%E5%88%86%E6%9E%90">理论性能分析</a> 章节。</p></blockquote></article></div>',1)])])}const E=a(d,[["render",o]]);export{l as __pageData,E as default};
